def desparse_permutation_table(tb):
	sparse_permutation_table = copy.deepcopy(tb)
	set_row_count = len(sparse_permutation_table)
	for i, row in enumerate(sparse_permutation_table):
		freespaces = row.count(-1)
		if freespaces == len(row): set_row_count -= 1
		unincluded = sorted(list(set(range(len(row))) - set(row)))
		j = 0
		for k, v in enumerate(row):
			if v == -1:
				row[k] = unincluded[j]
				j += 1
	print(f"{set_row_count = }")
	return sparse_permutation_table




